\documentclass{article}
\usepackage{pgfplots}
\usepackage{tikz}
\usetikzlibrary{arrows} %% Can be useful, not essential
\usetikzlibrary{intersections} %% Can be useful, not essential
\usepgfplotslibrary{fillbetween} %% Can be useful, not essential
\begin{document}
\pagestyle{empty} %% IMPORTANT
\begin{tikzpicture}

\draw (0.5,0) -- (5.5,0);
\draw[red, line width=0.5mm,<    -](0.5,0) -- (4,0);

\foreach \i in {1,...,4,5} % numbers on line
{
	\draw (\i,0.1) -- + (0,-0.2) node[below] {\small$\i$};
}
\node[circle,draw=red,fill,inner sep=2pt,fill=white] at (4,0) {};

\end{tikzpicture}
\end{document}

